-- Generated by scripts/season-pass-sql.mjs: never edit by hand. The Winter 2026 Season Pass and its pre-sale (21 Oct 2026).
-- Run once, in the SQL editor, BEFORE farm-api and the payment functions (diamond-checkout, stripe-webhook, play-voided,
-- app-store-notify) and the site. Everything runs in one transaction; a check that fails rolls all of it back.
begin;
set local lock_timeout='5s';

-- Guards: the functions this file replaces, and the ones the pre-sale relies on, are still the bodies read live on 21 Oct 2026.
do $d$
declare fn text; want text; got text;
begin
 for fn, want in select * from (values
  ('harvest_seasons()','cb6bc1bb197a30999fca0dfb6bd48244'),
  ('harvest_season_paid_looks(text)','f616b5c49f0d057524623ab0eee8f4f1'),
  ('harvest_season_target(text,jsonb)','0991b473f861dfe8f066804439a0483c'),
  ('harvest_season_refund()','2f9f80fcc0423f11661a79d578abaa53')) v(f,m) loop
  select md5(p.prosrc) into got from pg_proc p where p.oid=('public.'||fn)::regprocedure;
  if got is distinct from want then raise exception '% is not the body read on 21 Oct 2026 (md5 % instead of %): read it again and regenerate',fn,got,want; end if;
 end loop;
 if position('harvest_season_target' in (select p.prosrc from pg_proc p where p.oid='public.harvest_purchase_grant(uuid)'::regprocedure))=0 then
  raise exception 'harvest_purchase_grant does not use harvest_season_target: run season-pass-engine.sql first';
 end if;
 if not exists(select 1 from pg_indexes where schemaname='public' and indexname='harvest_one_season_per_player') then raise exception 'the one-season-per-player index is missing'; end if;
end $d$;

-- The seasons the game knows (game/farm-state.js SEASON_LIST; a test keeps this file equal to it): Autumn 2026, then Winter 2026.
create or replace function public.harvest_seasons() returns table(id text, ends_at timestamptz, claim_until timestamptz)
 language sql immutable set search_path to '' as $f$
 select * from (values
  ('autumn-2026',timestamptz '2026-12-22T00:00:00.000Z',timestamptz '2026-12-29T00:00:00.000Z'),
  ('winter-2026',timestamptz '2027-03-21T00:00:00.000Z',timestamptz '2027-03-28T00:00:00.000Z')) s(id,ends_at,claim_until)
$f$;
-- The paid looks of each season (its paid row, the avatar of the purchase too): what a refund takes off the farmer's card.
create or replace function public.harvest_season_paid_looks(p_pass text) returns text[] language sql immutable set search_path to '' as $f$
 select case p_pass
  when 'autumn-2026' then array['season-autumn-2026-harvest-chef','autumn-2026-color-pumpkin','autumn-2026-title-pumpkin-whisperer','autumn-2026-frame','autumn-2026-emblem','autumn-2026-bg-orchard','autumn-2026-color-apple-red','autumn-2026-golden-rod','autumn-2026-tractor','autumn-2026-title-autumn-legend','season-autumn-2026-pumpkin-royal','autumn-2026-golden-pumpkin']::text[]
  when 'winter-2026' then array['season-winter-2026-cocoa-maker','winter-2026-color-ice-blue','winter-2026-title-sledge-champion','winter-2026-frame','winter-2026-emblem','winter-2026-bg-valley','winter-2026-color-pine-green','winter-2026-frost-rod','winter-2026-tractor','winter-2026-title-winter-legend','season-winter-2026-frost-royal','winter-2026-golden-sledge']::text[]
  else array[]::text[] end
$f$;
-- This database grants EXECUTE to anon and authenticated by default: only the database itself and the service role call these.
revoke all on function public.harvest_seasons(), public.harvest_season_paid_looks(text) from public, anon, authenticated;
grant execute on function public.harvest_seasons(), public.harvest_season_paid_looks(text) to service_role;

-- After-checks: everything came out as generated, else nothing of this file stays.
do $d$
begin
 if (select count(*) from public.harvest_seasons())<>2 then raise exception 'season list'; end if;
 if (select s.ends_at from public.harvest_seasons() s where s.id='autumn-2026') is distinct from timestamptz '2026-12-22T00:00:00.000Z' then raise exception 'autumn end'; end if;
 if (select s.ends_at from public.harvest_seasons() s where s.id='winter-2026') is distinct from timestamptz '2027-03-21T00:00:00.000Z' then raise exception 'winter end'; end if;
 if (select s.claim_until from public.harvest_seasons() s where s.id='winter-2026') is distinct from timestamptz '2027-03-28T00:00:00.000Z' then raise exception 'winter collecting week'; end if;
 if cardinality(public.harvest_season_paid_looks('autumn-2026'))<>12 then raise exception 'autumn paid looks'; end if;
 if cardinality(public.harvest_season_paid_looks('winter-2026'))<>12 or not ('season-winter-2026-cocoa-maker' = any(public.harvest_season_paid_looks('winter-2026'))) then raise exception 'winter paid looks'; end if;
 -- A Winter purchase credits Winter (its collecting week is months away), also for a farm that has Autumn; an Autumn one Autumn while
 -- Autumn can still be collected.
 if public.harvest_season_target('winter-2026','{"passPremium":["autumn-2026"]}'::jsonb) is distinct from 'winter-2026' then raise exception 'winter target'; end if;
 if now()<timestamptz '2026-12-29T00:00:00.000Z' and public.harvest_season_target('autumn-2026','{"passPremium":["winter-2026"]}'::jsonb) is distinct from 'autumn-2026' then raise exception 'autumn target'; end if;
 if 'season-winter-2026-cocoa-maker' !~ '^season-[a-z0-9-]{3,60}$' or position('season-' in (select pg_get_constraintdef(c.oid) from pg_constraint c where c.conname='player_stats_avatar_id_check'))=0 then raise exception 'avatar check'; end if;
 if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'harvest_season%'
  and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute'))) then raise exception 'season functions open to players'; end if;
end $d$;

commit;
